add_shortcode( 'faq', 'perfectpixel_faq_shortcode' );
add_action( 'wp_footer', 'perfectpixel_faq_schema' );

function perfectpixel_faq_items( $item = null ) {
	static $items = array();
	if ( null !== $item ) {
		$items[] = $item;
	}
	return $items;
}

function perfectpixel_faq_shortcode( $atts, $content = '' ) {
	$atts     = shortcode_atts( array( 'question' => '', 'open' => 'no' ), $atts, 'faq' );
	$question = trim( $atts['question'] );
	if ( '' === $question ) {
		return '';
	}
	$answer = wpautop( do_shortcode( trim( (string) $content ) ) );
	perfectpixel_faq_items( array( 'q' => $question, 'a' => $answer ) );

	static $style_done = false;
	$style = '';
	if ( ! $style_done ) {
		$style_done = true;
		$style      = '<style>.perfectpixel-faq{border:1px solid rgba(0,0,0,.12);border-radius:4px;margin:0 0 .6em}.perfectpixel-faq summary{cursor:pointer;padding:.7em 1em;font-weight:600}.perfectpixel-faq[open] summary{border-bottom:1px solid rgba(0,0,0,.08)}.perfectpixel-faq .perfectpixel-faq-answer{padding:.7em 1em}.perfectpixel-faq .perfectpixel-faq-answer>:last-child{margin-bottom:0}</style>';
	}
	return $style . '<details class="perfectpixel-faq"' . ( 'yes' === $atts['open'] ? ' open' : '' ) . '><summary>' . esc_html( $question ) . '</summary><div class="perfectpixel-faq-answer">' . $answer . '</div></details>';
}

function perfectpixel_faq_schema() {
	$items = perfectpixel_faq_items();
	if ( ! $items ) {
		return;
	}
	$entities = array();
	foreach ( $items as $item ) {
		$entities[] = array(
			'@type'          => 'Question',
			'name'           => $item['q'],
			'acceptedAnswer' => array( '@type' => 'Answer', 'text' => wp_strip_all_tags( $item['a'] ) ),
		);
	}
	echo '<script type="application/ld+json">' . wp_json_encode( array( '@context' => 'https://schema.org', '@type' => 'FAQPage', 'mainEntity' => $entities ), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ) . '</script>' . "\n";
}
